  (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order)
VALUES
('CIT_NOR_SAGA_EDDA','ENT_NOR_SAGA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Saga, who dwells in Sokvabek, and this is a large dwelling.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_GEFJUN_EDDA','ENT_NOR_GEFJUN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Gefjun, who is a may, and those who die maids become her hand-maidens.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_SJOFN_EDDA','ENT_NOR_SJOFN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Sjofn, who is fond of turning men’s and women’s hearts to love, and it is from her name that love is called Sjafne.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_LOFN_EDDA','ENT_NOR_LOFN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Lofn, who is kind and good to those who call upon her, and she has permission from Alfather or Frigg to bring together men and women, no matter what difficulties may stand in the way; therefore “love” is so called from her name, and also that which is much loved by men.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_VAR_EDDA','ENT_NOR_VAR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Var.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_VOR_EDDA','ENT_NOR_VOR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Vor, who is so wise and searching that nothing can be concealed from her.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_SYN_EDDA','ENT_NOR_SYN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Syn, who guards the door of the hall, and closes it against those who are not to enter.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_HLIN_EDDA','ENT_NOR_HLIN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Hlin, who guards those men whom Frigg wants to protect from any danger.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_SNOTRA_EDDA','ENT_NOR_SNOTRA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Snotra, who is wise and courtly.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_GNA_EDDA','ENT_NOR_GNA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda (Gylfaginning)','Gylfaginning','The goddess is Gna, whom Frigg sends on her errands into various worlds.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'Named in Snorri Sturluson, Prose Edda (Gylfaginning); verify.',DATE '2026-06-26','name + substring gate against Snorri Sturluson, Prose Edda (Gylfaginning)',1),
('CIT_NOR_VK_HRIST_EDDA','ENT_NOR_VK_HRIST','SRC_POETIC_EDDA','The Poetic Edda (Grimnismal)','Grimnismal 36','Hrist and Mist the horn shall bear me Skeggold and Skogul, Hlokk and Herfiotur, Hildi and Thrudi, Goll and Geirolul, Randgrid and Radgrid, and Reginleif, these bear beer to the Einheriar.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'Named in The Poetic Edda (Grimnismal); verify.',DATE '2026-06-26','name + substring gate against The Poetic Edda (Grimnismal)',1),
